function power(a, p, m) {
  if (p === 0) {
    return 1;
  }
  if (p % 2 === 0) {
    const half = power(a, Math.floor(p / 2), m);
    return (half * half) % m;
  }
  return ((a % m) * power(a, p - 1, m)) % m;
}

