class Power {
  public int solve(int a, int p, int m) {
    if (p == 0) {
      return 1;
    }
    if (p % 2 == 0) {
      long half = solve(a, p / 2, m);
      return (int) ((half * half) % m);
    }
    return (int) (((long) a * solve(a, p - 1, m)) % m);
  }
}

